			'import * as React from "react";\nimport { Checkbox } from "@workspace/ui/components/checkbox";\nimport { Field, FieldContent, FieldDescription, FieldGroup, FieldLegend, FieldSeparator, FieldSet, FieldTitle } from "@workspace/ui/components/field";\nimport { Switch } from "@workspace/ui/components/switch";\n\nexport function Field10Example(): React.JSX.Element {\n\treturn (\n\t\t<div className="mx-auto w-full max-w-xs">\n\t\t\t<FieldGroup>\n\t\t\t\t<FieldSet>\n\t\t\t\t\t<FieldLegend variant="label">Notification Channels</FieldLegend>\n\t\t\t\t\t<FieldGroup className="gap-4">\n\t\t\t\t\t\t<Field orientation="horizontal">\n\t\t\t\t\t\t\t<FieldContent>\n\t\t\t\t\t\t\t\t<FieldTitle>Push Notifications</FieldTitle>\n\t\t\t\t\t\t\t\t<FieldDescription>Alerts sent to your device in real time.</FieldDescription>\n\t\t\t\t\t\t\t</FieldContent>\n\t\t\t\t\t\t\t<Switch id="notif-push" defaultChecked />\n\t\t\t\t\t\t</Field>\n\t\t\t\t\t\t<Field orientation="horizontal">\n\t\t\t\t\t\t\t<FieldContent>\n\t\t\t\t\t\t\t\t<FieldTitle>Email Digest</FieldTitle>\n\t\t\t\t\t\t\t\t<FieldDescription>A daily summary of activity sent to your inbox.</FieldDescription>\n\t\t\t\t\t\t\t</FieldContent>\n\t\t\t\t\t\t\t<Switch id="notif-email" defaultChecked />\n\t\t\t\t\t\t</Field>\n\t\t\t\t\t\t<Field orientation="horizontal">\n\t\t\t\t\t\t\t<FieldContent>\n\t\t\t\t\t\t\t\t<FieldTitle>SMS Alerts</FieldTitle>\n\t\t\t\t\t\t\t\t<FieldDescription>Text messages for critical notifications only.</FieldDescription>\n\t\t\t\t\t\t\t</FieldContent>\n\t\t\t\t\t\t\t<Switch id="notif-sms" />\n\t\t\t\t\t\t</Field>\n\t\t\t\t\t</FieldGroup>\n\t\t\t\t</FieldSet>\n\t\t\t\t<FieldSeparator />\n\t\t\t\t<FieldSet>\n\t\t\t\t\t<FieldLegend variant="label">Notify me about</FieldLegend>\n\t\t\t\t\t<FieldGroup className="gap-4">\n\t\t\t\t\t\t<Field orientation="horizontal">\n\t\t\t\t\t\t\t<Checkbox id="notif-comments" defaultChecked />\n\t\t\t\t\t\t\t<FieldContent>\n\t\t\t\t\t\t\t\t<FieldTitle>Comments</FieldTitle>\n\t\t\t\t\t\t\t\t<FieldDescription>When someone comments on your posts.</FieldDescription>\n\t\t\t\t\t\t\t</FieldContent>\n\t\t\t\t\t\t</Field>\n\t\t\t\t\t\t<Field orientation="horizontal">\n\t\t\t\t\t\t\t<Checkbox id="notif-mentions" defaultChecked />\n\t\t\t\t\t\t\t<FieldContent>\n\t\t\t\t\t\t\t\t<FieldTitle>Mentions</FieldTitle>\n\t\t\t\t\t\t\t\t<FieldDescription>When someone mentions you in a conversation.</FieldDescription>\n\t\t\t\t\t\t\t</FieldContent>\n\t\t\t\t\t\t</Field>\n\t\t\t\t\t\t<Field orientation="horizontal">\n\t\t\t\t\t\t\t<Checkbox id="notif-updates" />\n\t\t\t\t\t\t\t<FieldContent>\n\t\t\t\t\t\t\t\t<FieldTitle>Product Updates</FieldTitle>\n\t\t\t\t\t\t\t\t<FieldDescription>News about new features and improvements.</FieldDescription>\n\t\t\t\t\t\t\t</FieldContent>\n\t\t\t\t\t\t</Field>\n\t\t\t\t\t</FieldGroup>\n\t\t\t\t</FieldSet>\n\t\t\t</FieldGroup>\n\t\t</div>\n\t);\n}\n',
